with d as (select value r from jsonb_array_elements($q$[{"notes":["Use day-old rice for the best texture, fresh rice tends to clump when fried.","The corned beef tin is already cooked, so you're just heating and browning it for flavour.","Swap the fried egg for a sunny-side up or poached egg if you like, but that runny yolk over everything is the proper way to do it.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"5f82e99f-c80c-4569-ba17-c1e1335946b9"},{"notes":["The chicken can be cooked and shredded up to 1 day ahead; reheat gently in a low oven before plating. The chili oil keeps in a clean glass jar in the fridge for up to 2 weeks, use it on tofu, greens, or noodles.","Doubanjiang is spicy fermented bean paste from Sichuan; if you can't find it, skip this step rather than substituting, as it's essential to the flavour. Without it, this becomes a different (still good, but different) dish.","The numbing comes from the Sichuan peppercorns, not heat. If you prefer less mala, reduce them to 2 tablespoons.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Bring the 6 cups water to a boil in a large pot. Add the spring onion pieces, ginger slices, smashed garlic and salt. Simmer for 2 minutes to infuse the broth."},{"text":"Add the chicken pieces to the simmering broth and return to a gentle boil. Skim any scum that rises. Reduce heat to a low simmer and poach until the chicken is cooked through (check the thickest pieces reach 75°C inside), about 15 minutes. Remove the chicken to a plate and let cool slightly, then shred or cut into bite-sized pieces. Discard the poaching liquid."},{"text":"While the chicken cooks, make the chili oil. Heat the neutral oil in a small pan over medium heat. When it shimmers, add the Sichuan peppercorns and dried chillies. Toast, stirring gently, for 2–3 minutes until fragrant and the oil is a deep amber, do not let it smoke or burn."},{"text":"Remove the pan from heat. Add the doubanjiang, sliced garlic, sliced ginger, star anise and cinnamon stick. Stir well and let it infuse for 1 minute off the heat. The residual heat will open the flavours without charring them. Taste and add salt to balance."},{"text":"Arrange the shredded chicken on a serving plate. Pour the warm chili oil (including the aromatics and spices) over the chicken."},{"text":"Scatter with fresh coriander, chives, sliced spring onion and black sesame seeds if using. Serve warm or at room temperature with steamed rice."}],"id":"c0c1ba17-f3a3-4b6d-8812-b97a98ccee80"},{"notes":["If you don't have a proper cendol maker, use a fine sieve or even a ladle with small holes; the noodles don't need to be perfect, just thin.","Everything must be ice-cold before serving, chill the glasses if you want to be proper about it."],"steps":[{"text":"Make the syrup first: In a small saucepan, combine the palm sugar and 200 ml water. Stir over medium heat until the sugar dissolves completely, about 5 minutes. You should have a thick, smooth golden syrup. Remove from the heat and let it cool to room temperature."},{"text":"Make the cendol batter: In a bowl, mix the rice flour, 200 ml water, salt and the pandan leaves together, stirring until smooth and lump-free. The batter should be thin, like condensed milk in consistency. Remove the pandan leaves and set the batter aside."},{"text":"Bring a large pot of water to the boil (about 2 litres). Place the cendol maker (a special mould with holes, or use a sieve with small holes) over the boiling water. Working in batches, pour the batter slowly through the mould so the thin noodles drop straight into the boiling water. They will sink at first, then float to the surface in about 1 minute, that is when they are cooked."},{"text":"Remove the cooked cendol with a slotted spoon and place them immediately into a bowl of ice-cold water to stop the cooking. Drain well and set aside. Repeat with the remaining batter."},{"text":"In a small saucepan, warm the coconut milk gently over low heat until steaming, do not let it boil. Add a pinch of salt and stir. Let it cool to room temperature."},{"text":"To serve, divide the cendol noodles among four glasses or bowls, pour a little of the palm sugar syrup over them (about 50 ml per serving), then pour the cooled coconut milk on top (about 100 ml per serving). Fill each glass with ice and serve immediately, ice-cold."}],"id":"dc4e5408-3fa0-497b-93b9-a1f3736add1c"},{"notes":["The sambal can be made up to 2 hours ahead; keep it at room temperature so the flavours stay fresh and sharp.","Any firm white fish works here. Adjust cooking time by a minute or two depending on thickness.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"5b6fc878-cd4d-4c6b-8e77-c13d63841f0a"},{"notes":["This banchan keeps for up to three days refrigerated. It's equally good cold, straight from the bowl.","The quality of your sesame oil matters here, use a good toasted variety for the full nutty flavour."],"id":"eb576eac-0a6d-41c1-96c4-c88089973ac2"},{"notes":["The broken rice should have a slight bite, don't overcook it. If you can't find it, use jasmine rice but reduce the cooking time to 10 minutes.","Make the fish sauce caramel up to a day ahead and store in a jar; reheat gently before serving.","Pickled daikon and carrot (cà chua cà rốt) from the supermarket are traditional but optional, they add a salty, vinegary edge.","Food safety: Cook fresh pork to at least 70°C in the thickest part. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"1d65f0da-3443-4be2-a3fa-307eb4614749"},{"notes":["Make the toasted rice powder ahead and keep it in a jar, it will keep for weeks and makes larb het much quicker on the day.","Larb het is best served at room temperature or warm. It doesn't keep well, so make it just before you want to eat."],"id":"47e934bd-39a4-4dce-b40f-7816dc60caa9"},{"diets":["no-gluten"],"id":"eb953ab7-ab39-41ba-a471-d29b56e61b10"},{"notes":["The kanji keeps in the fridge for up to 10 days, and the vada soften into it beautifully.","If you don't have a wet grinder, a good blender works fine, just be patient and add water slowly so the batter stays light."],"steps":[{"text":"Make the kanji first. Heat the mustard oil in a pan until it just smokes, then remove from heat. When it has cooled to warm, add the mustard seeds, fenugreek seeds, and dried chillies. Let them crackle for a few seconds, then stir in the asafoetida. In a jar, combine the carrot sticks with salt, then pour the hot oil and spices over them. Add the citric acid, stir well, and set aside to cool completely."},{"text":"Drain the urad dal and grind it to a thick, smooth paste using a wet grinder or food processor, adding just a splash of water if needed, the batter should be light and fluffy, not wet."},{"text":"Transfer the batter to a bowl. Fold in the rice flour, green chilli, cumin seeds, and salt, mixing gently to keep the batter airy."},{"text":"Heat the oil for frying in a large, heavy pan to 180°C (a small piece of batter should sizzle and rise to the top immediately)."},{"text":"Wet your fingers and shape small balls of batter about the size of a walnut, then gently slide them into the hot oil. Fry in batches until golden and crisp all over, being careful not to crowd the pan."},{"text":"Fry for 4 to 5 minutes, stirring gently and turning the vada so they brown evenly. They should be golden and crispy. Remove with a slotted spoon and drain on paper towel."},{"text":"Once the vada have cooled to room temperature, add them to the kanji jar and mix gently so each one is coated with the pickle. Cover and leave for at least 4 hours, or overnight, before serving."}],"id":"5398211e-2ce8-421c-bbd0-558c3a551c28"},{"notes":["This is traditionally made in a heavy pot called a dizi. An enamelled cast iron or stainless steel pot works just as well.","Some cooks add dried limes (loomi) or a pinch of saffron for extra depth. This version keeps it simple.","The broth keeps well for 3 days in the fridge, and tastes even better the next day.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the oil in a large heavy pot over medium-high heat. Brown the beef chunks on all sides, about 8 minutes total. Don't rush this step."},{"text":"Add the onions and turmeric, stirring, until fragrant, about 2 minutes."},{"text":"Pour in the water and bring to a boil. Skim any foam from the surface until the liquid looks clear. Add the black pepper and a pinch of salt."},{"text":"Reduce to a low simmer, cover, and cook for 45 minutes."},{"text":"Add the potatoes and chickpeas, and simmer, covered, for another 45 minutes until the meat is very tender and the broth is rich and deep in colour."},{"text":"Taste and adjust the salt. You should have a clear, flavourful broth and very soft solids."},{"text":"To serve, ladle the broth into bowls as the first course. Pour the remaining broth over the meat and vegetables."},{"text":"Pound the cooked meat and potatoes with a wooden spoon or potato masher directly in the pot until roughly crushed. Pile onto toasted bread, drizzle with a little broth, and serve as the second course. Garnish with fresh herbs if you have them."}],"id":"2d09ee45-4f29-4440-bf9b-84084dd4f3ef"},{"notes":["Cook from leftover rotisserie chicken or use tinned tuna (drained) for a different angle.","The gravy thickens as it cools slightly, aim for thick but pourable at the stove.","Scale up easily: double the stock and starch for two bowls, cook noodles separately.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"steps":[{"text":"Bring a pot of salted water to a rolling boil. Cook the egg noodles until soft, about 3–4 minutes, stirring gently to prevent sticking. Drain and tip into a bowl."},{"text":"In the same pot (no need to rinse), heat the oil over medium heat. Add the minced garlic and fry gently until fragrant and golden, about 1 minute, don't burn it."},{"text":"Pour in the chicken stock and bring to a simmer until the sauce is bubbling gently. Add the soy sauce and sugar, then taste. Adjust salt and white pepper to your liking."},{"text":"Stir the tapioca starch mixture to recombine it (it will have settled), then slowly pour it into the simmering stock while stirring constantly. Keep stirring for 1–2 minutes until the gravy thickens and turns glossy and translucent."},{"text":"Add the shredded chicken and stir to heat through, about 1 minute. The gravy should be thick enough to coat the back of a spoon but still pour easily."},{"text":"Place the soft noodles in a bowl and carefully pour the hot gravy over them. Top with fried garlic, fresh coriander if you have it, and pickled chilli if you like heat. Eat while it's hot."}],"id":"389716ca-4477-4e4d-a401-9b281f94ba5a"},{"notes":["Clean the clams by scrubbing them under cold water and soaking in salted water for an hour if you have time; this helps them expel sand.","Make-ahead: prepare the dashi and have the clams cleaned and ready the night before. The soup itself takes just 15 minutes on the day.","If clams are very large, you can halve them after opening for easier eating.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Throw away any mussels or clams whose shells stay closed after cooking."],"steps":[{"text":"Bring the dashi to a gentle simmer in a pot until tiny bubbles rise at the edges."},{"text":"Add the cleaned clams and a thin slice of ginger if using. Cover and simmer until the clams just begin to open, 3 to 4 minutes."},{"text":"Scoop the clams into serving bowls as they open (don't wait for all of them; they open in stages)."},{"text":"Dissolve the white miso in a small bowl with a ladle of the hot broth until smooth, then pour it back into the pot. Stir gently, do not let the broth boil or the miso flavour will flatten."},{"text":"Add the mirin to the pot and taste. Add a small pinch of salt if needed."},{"text":"Pour the broth over the clams in each bowl, scatter the spring onion on top, and serve immediately."}],"id":"7f1b3133-3e1e-4561-854e-e51d5b9da043"},{"notes":["You can make the broth a day ahead; store it in the fridge and add the prawns just before serving.","Quesillo or fresh mozzarella works best here, it melts into silken clouds in the hot broth. Avoid hard cheeses.","If you can't find ají amarillo paste, substitute 2 tsp of ají amarillo powder mixed with a little water.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Heat oil in a large pot over medium heat. Add onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Stir in garlic and ají amarillo paste, cooking for 1 minute until fragrant."},{"text":"Pour in stock and bring to a simmer. Add potato and capsicum, then stir in cumin. Cook for 12–15 minutes, until potato is just tender."},{"text":"Season with salt and pepper. Add prawns and cook, stirring gently, until they turn opaque and firm, about 3–4 minutes. Do not overcook."},{"text":"Remove from heat. Divide fresh cheese among serving bowls, then ladle the hot chupe over it, the cheese will soften and melt into the broth."},{"text":"Top each bowl with two egg halves and garnish with coriander if you like. Serve immediately."}],"id":"1b0ec94d-9745-4329-a482-d8717b62ae3f"},{"steps":[{"text":"If you have a gas stove, char the tomatoes, chillies and garlic directly over the flame, turning with tongs, until blackened and soft all over, about 10–12 minutes. If you only have electric, use a grill pan or cast iron over high heat, turning often, until deeply charred. The darker the better."},{"text":"Let cool for a minute, then peel away the charred skin from the tomatoes and discard. Peel the garlic cloves."},{"text":"Pound the charred tomatoes, chillies and garlic in a mortar and pestle until you have a rough paste, it should be chunky, not smooth."},{"text":"Stir in the lime juice and fish sauce. Taste and add salt if needed. The dip should be smoky, hot and sharp all at once."}],"id":"5bbb3bce-cb39-4df3-96fc-41b9a2ff8089"},{"notes":["Make ahead: Shape the kebabs up to 4 hours ahead and refrigerate on a lined tray, covered.","For extra crunch, add 2 tbsp finely chopped pistachios or almonds to the mince.","Serve with naan or flatbread, sliced onions, lemon and a dollop of cooling yoghurt.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"steps":[{"text":"In a large bowl, combine the lamb mince, pomegranate seeds, green chilli, onion, garlic, fresh coriander, mint and egg. Add the ground cumin, ground coriander, chilli powder, garam masala and salt. Mix gently with your hands until just combined, don't overwork it or the kebabs will be dense."},{"text":"Divide the mixture into 8 equal portions. Wet your hands lightly and shape each portion into a thick oval, pressing gently but firmly so it holds together."},{"text":"Heat a large frying pan or tawa over medium-high heat and add 2 tbsp oil. Once shimmering, carefully place 4 kebabs in the pan without crowding."},{"text":"Cook for 5 to 6 minutes on the first side until golden brown and crispy, then flip carefully. Cook for another 3 to 4 minutes until the second side is golden and the meat is cooked through (the internal temperature should reach 75°C)."},{"text":"Transfer to a paper-towel-lined plate and cook the remaining 4 kebabs in the same way, adding a little more oil if needed, until each is deep golden brown and crisp at the edges."},{"text":"Serve hot with lemon wedges, sliced onions and yoghurt on the side."}],"id":"07f24072-41e2-48c3-a4ef-1a360cf3f6ff"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;